// Builds android/app/src/main/assets/goppo-bridge.js: the official @capacitor/core runtime (IIFE build) plus a lazy
// registration of the GoppoNative plugin. MainActivity/GoppoBridgeShim injects it at document start into the live
// website (only for the website origin), so `Capacitor.Plugins.GoppoNative` exists before platform.js runs.
import { readFileSync, writeFileSync, mkdirSync } from "node:fs";
import { dirname, resolve } from "node:path";
import { fileURLToPath } from "node:url";

const root = resolve(dirname(fileURLToPath(import.meta.url)), "..");
const corePath = resolve(root, "node_modules/@capacitor/core/dist/capacitor.js");
const out = resolve(root, "android/app/src/main/assets/goppo-bridge.js");

const core = readFileSync(corePath, "utf8").replace(/\/\/# sourceMappingURL=.*$/m, "");
const version = JSON.parse(readFileSync(resolve(root, "node_modules/@capacitor/core/package.json"), "utf8")).version;

// ORDER MATTERS. Capacitor's own document-start script starts with `window.Capacitor = {...}` (it replaces the object),
// then installs the native bridge, a deprecated "legacy" Capacitor.Plugins.GoppoNative proxy and Capacitor.PluginHeaders.
// This script is registered AFTER it (GoppoBridgeShim.install, from MainActivity.onCreate), so it can extend that object:
// @capacitor/core adds registerPlugin(), and registerPlugin("GoppoNative") replaces the legacy proxy with the official one
// (built from PluginHeaders, calling the native bridge). Everything runs before platform.js.
const register = `
;(function () {
  try {
    var cap = window.Capacitor;
    if (!cap || typeof cap.registerPlugin !== "function") return;
    var headers = cap.PluginHeaders || [];
    ["GoppoNative", "GoppoLocal"].forEach(function (name) {
      var present = false;
      for (var i = 0; i < headers.length; i++) if (headers[i] && headers[i].name === name) present = true;
      if (present) cap.registerPlugin(name);    // sets Capacitor.Plugins.<name>; a plugin missing from this app is left alone
    });
  } catch (e) { /* never break the page */ }
})();
`;

const banner = `/* Goppo bridge: @capacitor/core ${version} + GoppoNative registration. Generated by scripts/build-bridge.mjs - do not edit. */\n`;
mkdirSync(dirname(out), { recursive: true });
writeFileSync(out, banner + core + "\n" + register);
console.log("wrote", out, `(${(banner + core + register).length} bytes, @capacitor/core ${version})`);
